cssCode:
.steam-container {
  display: flex; gap: 10px; justify-content: center; align-items: flex-end;
  width: 100px; height: 100px; border-bottom: 4px solid #ff9900;
  padding-bottom: 10px; border-radius: 10px;
}
.steam {
  width: 8px; background: rgba(255, 255, 255, 0.6);
  border-radius: 10px; filter: blur(2px);
  animation: riseSteam 2s infinite ease-in; opacity: 0;
}
.steam:nth-child(1) { animation-delay: 0s; height: 40px; }
.steam:nth-child(2) { animation-delay: 0.5s; height: 60px; }
.steam:nth-child(3) { animation-delay: 1s; height: 50px; }

@keyframes riseSteam {
  0% { transform: translateY(0) scaleX(1); opacity: 0; }
  50% { opacity: 1; transform: translateY(-30px) scaleX(1.5); }
  100% { transform: translateY(-60px) scaleX(2); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const steamBox = document.createElement('div');
steamBox.className = 'steam-container';

for(let i=0; i<3; i++) {
  const s = document.createElement('div');
  s.className = 'steam';
  steamBox.appendChild(s);
}
c.appendChild(steamBox);
